# Full-page loading screen. Delimiter is ~ (absent from the code) so # and | are safe.
# 1. CSS right after the [hidden] reset
s~  \[hidden\]\{display:none!important\}\n~  [hidden]{display:none!important}\n  /* ---------- full-page loading screen */\n  .site-loader{position:fixed;inset:0;z-index:1000;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:36px;background-color:\#0A0A0C;background-image:radial-gradient(ellipse 70% 45% at 50% 26%,rgba(255,255,255,.045),transparent 70%),radial-gradient(ellipse 42% 22% at 50% 64%,rgba(0,255,102,.05),transparent 70%),radial-gradient(circle at 50% 50%,rgba(255,255,255,.035) 0 .8px,transparent 1.4px),radial-gradient(circle at 0 0,rgba(255,255,255,.028) 0 .8px,transparent 1.4px);background-size:100% 100%,100% 100%,6px 6px,6px 6px;background-position:0 0,0 0,0 0,3px 3px;transition:opacity .7s ease,visibility .7s;font-family:var(--body)}\n  .site-loader.out{opacity:0;visibility:hidden;pointer-events:none}\n  html.is-loading{overflow:hidden}\n  .sl-head{display:flex;flex-direction:column;align-items:center;gap:14px;opacity:0;transition:opacity .5s ease}\n  .site-loader.fonts .sl-head{opacity:1}\n  .sl-title{font-family:var(--wordmark);font-size:clamp(28px,4vw,44px);line-height:1;letter-spacing:.14em;padding-left:.14em;background:linear-gradient(180deg,\#F4F6F7 0%,\#C9CED3 48%,\#8D949B 100%);-webkit-background-clip:text;background-clip:text;color:transparent}\n  .sl-sub{font:600 10.5px/1 var(--body);letter-spacing:.32em;padding-left:.32em;text-transform:uppercase;color:\#6F7983;text-align:center}\n  .sl-row{display:flex;align-items:center;gap:16px}\n  .sl-frame{position:relative;width:min(340px,62vw);padding:3px;border-radius:7px;background:linear-gradient(180deg,\#2b2f34,\#15181b);box-shadow:inset 0 1px 0 rgba(255,255,255,.14),inset 0 -1px 0 rgba(0,0,0,.7),0 1px 0 rgba(255,255,255,.04),0 6px 18px rgba(0,0,0,.6)}\n  .sl-track{position:relative;height:6px;border-radius:4px;background:\#0b0d0f;box-shadow:inset 0 1px 2px rgba(0,0,0,.9);overflow:hidden}\n  .sl-fill{position:absolute;top:0;bottom:0;left:0;width:4%;border-radius:4px;background:linear-gradient(180deg,\#5CFF9C,\#00FF66 55%,\#00C853);box-shadow:0 0 12px rgba(0,255,102,.7),0 0 30px rgba(0,255,102,.35);transition:width .3s ease-out}\n  .sl-spill{position:absolute;left:3px;top:100%;height:70px;width:4%;margin-top:-4px;background:radial-gradient(ellipse 60% 100% at 50% 0,rgba(0,255,102,.3),transparent 70%);filter:blur(10px);pointer-events:none;transition:width .3s ease-out}\n  .sl-pct{font:500 12px/1 var(--mono);color:\#8A939C;min-width:3.2em;font-variant-numeric:tabular-nums}\n  .sl-label{position:absolute;bottom:36px;left:0;right:0;text-align:center;font:500 10.5px/1 var(--mono);letter-spacing:.18em;text-transform:uppercase;color:\#4E565D}\n  \@media (prefers-reduced-motion:reduce){.sl-fill,.sl-spill,.site-loader,.sl-head{transition:none}}\n~;
# 2. markup + controller right after the skip link
s~(<a class="skip" href="\#main">Skip to content</a>\n)~$1<div class="site-loader" id="siteLoader" role="status" aria-live="polite" aria-label="Loading GASMAX">\n  <div class="sl-head"><div class="sl-title">GASMAX</div><div class="sl-sub">The premier on-chain refueling protocol</div></div>\n  <div class="sl-row"><div class="sl-frame"><div class="sl-track"><div class="sl-fill"></div></div><div class="sl-spill"></div></div><div class="sl-pct">4%</div></div>\n  <div class="sl-label">Loading pit lane</div>\n</div>\n<script>\n(() => {\n  const el = document.getElementById(\x27siteLoader\x27); if (!el) return;\n  const fill = el.querySelector(\x27.sl-fill\x27), spill = el.querySelector(\x27.sl-spill\x27), pct = el.querySelector(\x27.sl-pct\x27), lbl = el.querySelector(\x27.sl-label\x27);\n  const reduced = window.matchMedia && window.matchMedia(\x27(prefers-reduced-motion: reduce)\x27).matches;\n  let p = 0.04, target = 0.3, shown = 0.04, finished = false;\n  const t0 = performance.now();\n  document.documentElement.classList.add(\x27is-loading\x27);\n  const paint = () => { const w = (shown * 100).toFixed(1) + \x27%\x27; fill.style.width = w; spill.style.width = w; pct.textContent = Math.round(shown * 100) + \x27%\x27; };\n  const tick = () => { if (finished) return; if (shown < p) shown = reduced ? p : Math.min(p, shown + Math.max(0.004, (p - shown) * 0.12)); else if (!reduced && shown < target - 0.02) shown += 0.0012; paint(); requestAnimationFrame(tick); };\n  window.__loading = {\n    set(f, label) { if (finished) return; p = Math.max(p, Math.min(0.97, f)); target = Math.max(target, Math.min(0.97, f + 0.15)); if (label && lbl) lbl.textContent = label; },\n    done() { if (finished) return; finished = true; p = 1; shown = 1; paint(); if (lbl) lbl.textContent = \x27Ready\x27; const wait = Math.max(0, 900 - (performance.now() - t0)); setTimeout(() => { el.classList.add(\x27out\x27); document.documentElement.classList.remove(\x27is-loading\x27); setTimeout(() => el.remove(), 800); }, wait + 220); }\n  };\n  window.__loading.fail = window.__loading.done;\n  if (document.fonts && document.fonts.ready) document.fonts.ready.then(() => el.classList.add(\x27fonts\x27));\n  setTimeout(() => el.classList.add(\x27fonts\x27), 700);\n  window.addEventListener(\x27load\x27, () => window.__loading.set(0.3));\n  setTimeout(() => { if (!finished && p <= 0.3) { const sc = document.querySelector(\x27.scene\x27); if (sc) sc.classList.add(\x27nogl\x27); window.__loading.done(); } }, 12000);\n  setTimeout(() => window.__loading.done(), 30000);\n  requestAnimationFrame(tick);\n})();\n</script>\n~;
# 3. hooks in the 3D module
s~const setProgress = \(f, label\) => \{ if \(bar\) bar\.style\.width = Math\.max\(4, Math\.round\(f \* 100\)\) \+ \x27%\x27; if \(txt && label\) txt\.textContent = label; \};~const setProgress = (f, label) => { if (bar) bar.style.width = Math.max(4, Math.round(f * 100)) + \x27%\x27; if (txt && label) txt.textContent = label; if (window.__loading) window.__loading.set(f, label); };~;
s~const showFallback = \(\) => \{ if \(sceneEl0\) sceneEl0\.classList\.add\(\x27nogl\x27\); \};~const showFallback = () => { if (sceneEl0) sceneEl0.classList.add(\x27nogl\x27); if (window.__loading) window.__loading.done(); };~;
s~requestAnimationFrame\(frame\);\nwindow\.__rig = \{~requestAnimationFrame(frame);\nrequestAnimationFrame(() => requestAnimationFrame(() => { if (window.__loading) window.__loading.done(); }));\nwindow.__rig = {~;
